import math

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def control(obs):
    hitch = float(obs.get('hitch_deg', 0.0))
    route = obs.get('route', {})
    bearing = float(route.get('bearing_deg', 0.0))
    steer = -1.25 * bearing + 0.65 * hitch
    sensors = obs.get('sensors', {})
    tr = sensors.get('trailer', {})
    vals = []
    for key in ('rear_left', 'rear_right', 'left', 'right'):
        if key in tr:
            try: vals.append(float(tr[key]))
            except: pass
    clearance = min(vals) if vals else 1.0
    lm = obs.get('local_map', {})
    left, right = lm.get('left_rail', []), lm.get('right_rail', [])
    offsets = []
    for u in (4, 6, 8, 10):
        def at(seq):
            if not seq: return None
            p = min(seq, key=lambda q: abs(float(q[0]) - u))
            return float(p[1])
        a, b = at(left), at(right)
        if a is not None and b is not None: offsets.append((a+b)*0.5)
    if offsets: steer += clamp(-0.25 * sum(offsets)/len(offsets), -5.0, 5.0)
    steer = clamp(steer, -24.0, 24.0)
    speed = -0.75
    if clearance < 0.9: speed = -0.35
    if abs(hitch) > 30: speed = -0.4
    if abs(hitch) > 48:
        speed = -0.2
        steer = clamp(1.15*hitch, -28, 28)
    if obs.get('status') == 'JACKKNIFED': return (0.0, 1.2, 180.0)
    return (steer, speed, 180.0)

