import math
def clamp(x, lo, hi): return max(lo, min(hi, x))
def control(obs):
    hitch = float(obs.get('hitch_deg', 0.0))
    motion = obs.get('motion', {})
    sensors = obs.get('sensors', {})
    vehicle = sensors.get('vehicle', {})
    route = obs.get('route', {})
    bearing = float(route.get('bearing_deg', 0.0))
    # Clear the very close right side and let forward motion unwind the hitch.
    if abs(hitch) > 6.0 or float(vehicle.get('right', 9.0)) < 0.9:
        return (12.0, 0.45, 180.0)
    # Reverse at low speed, using route alignment and hitch feedback.
    steer = clamp(-0.8 * bearing + 0.5 * hitch, -16.0, 16.0)
    trailer = sensors.get('trailer', {})
    near = min([float(trailer[k]) for k in ('rear_left','rear_right','left','right') if k in trailer] or [2.0])
    speed = -0.35 if near < 1.1 or abs(hitch) > 22 else -0.55
    if abs(hitch) > 38:
        return (clamp(0.8 * hitch, -20.0, 20.0), -0.25, 180.0)
    return (steer, speed, 180.0)

