import math
def clamp(x, lo, hi): return max(lo, min(hi, x))
def control(obs):
    hitch = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status', '')
    sensors = obs.get('sensors', {})
    vehicle = sensors.get('vehicle', {})
    if status in ('PULLING_FORWARD', 'PINNED') and abs(hitch) > 2.0:
        return (0.0, 0.30, 180.0)
    lm = obs.get('local_map', {})
    left, right = lm.get('left_rail', []), lm.get('right_rail', [])
    mids = []
    for u in (2, 4, 6, 8):
        def nearest(seq):
            if not seq: return None
            p = min(seq, key=lambda q: abs(float(q[0])-u))
            return float(p[1])
        a, b = nearest(left), nearest(right)
        if a is not None and b is not None: mids.append((a+b)*0.5)
    center = sum(mids)/len(mids) if mids else 0.0
    steer = clamp(-0.65*center + 0.32*hitch, -12.0, 12.0)
    near = 2.0
    for key in ('left','right','front_left','front_right'):
        try: near = min(near, float(vehicle[key]))
        except: pass
    speed = -0.18 if near < 0.8 else -0.24
    return (steer, speed, 180.0)

