def clamp(x, lo, hi): return max(lo, min(hi, x))
def sample(seq, u):
    if not seq: return None
    p = min(seq, key=lambda q: abs(float(q[0])-u))
    return float(p[1])
def control(obs):
    lm = obs.get('local_map', {})
    left, right = lm.get('left_rail', []), lm.get('right_rail', [])
    centers = []
    for u in (0, 2, 4, 6):
        a, b = sample(left, u), sample(right, u)
        if a is not None and b is not None: centers.append((a+b)*0.5)
    center = sum(centers)/len(centers) if centers else 0.0
    hitch = float(obs.get('hitch_deg', 0.0))
    steer = clamp(-2.0*center + 0.30*hitch, -12.0, 12.0)
    sensors = obs.get('sensors', {})
    clear = []
    for group, keys in ((sensors.get('trailer', {}), ('left','right','rear_left','rear_right')), (sensors.get('vehicle', {}), ('left','right','front_left','front_right'))):
        for k in keys:
            try: clear.append(float(group[k]))
            except: pass
    near = min(clear) if clear else 2.0
    speed = -0.16 if near < 0.8 or abs(hitch) > 25 else -0.22
    return (steer, speed, 180.0)

