def control(obs):
    hitch = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status', '')
    vehicle = obs.get('sensors', {}).get('vehicle', {})
    try: left = float(vehicle.get('left', 9.0))
    except: left = 9.0
    # Clear the close left rail and let the trailer unwind before reversing again.
