import math

def control(obs):
    lm = obs.get('local_map', {})
    left = lm.get('left_rail', [])
    right = lm.get('right_rail', [])
    def interp(points, u):
        if not points: return None
        pts = sorted(points, key=lambda p: p[0])
        if u <= pts[0][0]: return pts[0][1]
        if u >= pts[-1][0]: return pts[-1][1]
        for a, b in zip(pts, pts[1:]):
            if a[0] <= u <= b[0]:
                f = (u-a[0])/(b[0]-a[0])
                return a[1] + f*(b[1]-a[1])
        return None
    target_u = 2.2
    vl, vr = interp(left, target_u), interp(right, target_u)
    if vl is not None and vr is not None:
        center_v = (vl + vr) / 2.0
        bearing = math.degrees(math.atan2(center_v, target_u))
    else:
        bearing = obs.get('route', {}).get('bearing_deg', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    steer = max(-27.0, min(27.0, -1.35*bearing + 0.9*hitch))
    remaining = obs.get('progress', {}).get('remaining', 13.2)
    speed = -0.65 if remaining > 2.0 else -0.35
    if abs(hitch) > 32:
        steer = max(-36.0, min(36.0, 1.15*hitch - 1.1*bearing))
        speed = -0.28
    return (steer, speed)

