    veh = sensors.get('vehicle', {})
    try:
        fr = float(veh.get('front_right', 9.0))
    except (TypeError, ValueError):
        fr = 9.0
    if obs.get('status') == 'PINNED' or fr < 2.2:
        return (42.0, 0.45, 180.0)
    h = float(obs.get('hitch_deg', 0.0))
    bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
    target = max(-25.0, min(-6.0, 0.45 * bearing))
    steer = max(-24.0, min(24.0, 0.9 * (h - target)))
    trailer = sensors.get('trailer', {})
    try:
        rl = float(trailer.get('rear_left', 9.0))
    except (TypeError, ValueError):
        rl = 9.0
    speed = -0.14 if rl < 2.0 else -0.20
    return (steer, speed, 180.0)

