def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    sensors = obs.get('sensors', {})
    veh = sensors.get('vehicle', {})
    try:
        fl = float(veh.get('front_left', 9.0))
    except (TypeError, ValueError):
        fl = 9.0
    # Open clearance and reduce the large articulation while moving forward.
    if obs.get('motion', {}).get('v_mps', 0.0) >= -0.01 and (abs(h) > 9.0 or fl < 2.0):
        return (-24.0 if fl < 2.0 else 0.0, 0.40, 180.0)
    bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
    target = max(-10.0, min(4.0, 0.35 * bearing))
    steer = max(-18.0, min(18.0, 0.8 * (h - target)))
    trailer = sensors.get('trailer', {})
    try:
        rl = float(trailer.get('rear_left', 9.0))
        rr = float(trailer.get('rear_right', 9.0))
    except (TypeError, ValueError):
        rl, rr = 9.0, 9.0
    speed = -0.18 if min(rl, rr) < 2.0 else -0.24
    return (steer, speed, 180.0)

