def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    sensors = obs.get('sensors', {})
    veh = sensors.get('vehicle', {})
    def val(k, default=9.0):
        try: return float(veh.get(k, default))
        except (TypeError, ValueError): return default
    left = min(val('left'), val('front_left'))
    right = min(val('right'), val('front_right'))
    # Negative steering increases a negative hitch angle while reversing;
    # use positive steering to bring this negative angle back toward zero.
    steer = max(-8.0, min(8.0, -0.45 * h))
    # Hold a small rightward correction if the truck approaches its left rail.
    if left < 1.6: steer = max(steer, 3.0)
    if right < 1.6: steer = min(steer, -3.0)
    speed = -0.05 if min(left, right) < 1.8 else -0.09
    return (steer, speed, 180.0)

